"use strict";(globalThis.webpackChunkmy_website||=[]).push([[88382],{16754(e){e.exports=JSON.parse('{"slug":"bridge","title":"Bridge","short":"A protocol that connects Cardano to another blockchain so assets or messages can move between them; typically a pair of contracts that lock value on one chain and mint a representation on the other.","category":"network","aliases":[],"mentalModel":"A bridge does not literally move a token between chains. It locks the original on one side and mints a stand-in on the other. The stand-in is only worth what the lock-up still holds, which is why bridge security is mostly about the safety of that lock.","related":["stablecoin","sidechains"],"sources":[],"link":null,"level":"beginner","body":"See [bridge apps](/apps/?tags=bridge) for current options on Cardano."}')}}]);